-- 2026_10_08_000003_auth_additions
-- ================================================================
-- =====================================================================
-- Migration 0003: Phase 2 authentication additions
-- =====================================================================

SET NAMES utf8mb4;

CREATE TABLE email_verifications (
    id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    user_id     BIGINT UNSIGNED NOT NULL,
    email       VARCHAR(191) NOT NULL COMMENT 'address being verified (user may change email later)',
    token_hash  CHAR(64) NOT NULL,
    expires_at  DATETIME NOT NULL,
    used_at     DATETIME NULL,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_email_verifications_token (token_hash),
    KEY idx_email_verifications_user (user_id),
    CONSTRAINT fk_email_verifications_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE users
    ADD COLUMN terms_accepted_at   DATETIME NULL AFTER email_verified_at,
    ADD COLUMN password_changed_at DATETIME NULL AFTER password_hash;

-- ================================================================
-- 2026_10_08_000004_posting_wizard
-- ================================================================
-- =====================================================================
-- Migration 0004: Phase 4 property posting wizard
-- =====================================================================
-- Owners can type their area when it is not in the admin's locality list
-- (only Surat has localities seeded). locality_id stays NULL in that case;
-- the admin can later add the area to the list and link it.

SET NAMES utf8mb4;

ALTER TABLE properties
    ADD COLUMN locality_name VARCHAR(100) NULL COMMENT 'typed by owner when the area is not in localities' AFTER locality_id;

-- ================================================================
-- 2026_10_09_000005_performance_indexes
-- ================================================================
-- =====================================================================
-- Migration 0005: Phase 14 performance indexes
-- =====================================================================
-- Measured with 20,000 listings:
-- * (status, expires_at) made MariaDB pick it for every public listing
--   query (key on status only), reading all active rows before sorting.
--   Expiry is now indexed on its own; the cron job still finds expired
--   listings with a range scan.
-- * The admin property list sorts by updated_at (and the approval queue by
--   submitted_at); both were full-table sorts.
-- * The homepage "newest listings" across all purposes needs
--   (status, published_at) to read the newest rows straight from the index.
